using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Input;
using System.Text.Json;
namespace StarlightSyndicateDemo;
public static class FoundationTestsJ
{
 public static void Run(){int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception("J FAIL: "+label);checks++;Console.WriteLine("J PASS: "+label);}var edit=new TextEditJ();edit.Set("alpha beta");edit.Key(Keys.Home,false,false);edit.Key(Keys.Right,true,false);edit.Insert("A");Check(edit.Value=="Alpha beta","selection replacement");edit.Key(Keys.End,false,false);edit.Key(Keys.Back,false,false);Check(edit.Value=="Alpha bet","backspace");edit.Key(Keys.Home,false,false);edit.Key(Keys.Delete,false,false);Check(edit.Value=="lpha bet","delete");edit.Key(Keys.A,false,true);edit.Insert("search");Check(edit.Value=="search"&&edit.Cursor==6,"select all replace");edit.Key(Keys.Home,false,false);edit.Key(Keys.Right,true,false);Check(edit.Selection==(0,1),"shift selects");edit.Key(Keys.End,false,false);Check(edit.Selection.Length==0,"navigation collapses selection");
 var layout=new DesktopLayoutJ{Windows=[new(){Kind=ViewMode.Inventory,InstanceId="one",Width=600,Height=400,InventoryHangarJ=true,InventoryScrollJ=3,Locked=true,Opacity=.7f},new(){Kind=ViewMode.Inventory,InstanceId="two",Width=700,Height=450,InventoryHangarJ=false},new(){Kind=ViewMode.OverviewJ,InstanceId="overview",PresetJ="Hostiles",ColumnsJ=[new(){Id="distance",Width=95}]}]};DemoGame.ValidateLayoutJ(layout);var round=JsonSerializer.Deserialize<DesktopLayoutJ>(JsonSerializer.Serialize(layout))!;Check(round.Windows.Select(w=>w.Owner).Distinct().Count()==3,"independent identities");Check(round.Windows[0].InventoryHangarJ&&!round.Windows[1].InventoryHangarJ,"inventory locations independent");Check(round.Windows[0].Locked&&round.Windows[0].Opacity==.7f,"chrome preferences roundtrip");Check(round.Windows[2].PresetJ=="Hostiles"&&round.Windows[2].ColumnsJ[0].Width==95,"table config roundtrip");bool rejects=false;round.Windows.Add(round.Windows[0]);try{DemoGame.ValidateLayoutJ(round);}catch(InvalidDataException){rejects=true;}Check(rejects,"duplicate window identity rejected");round.Windows.RemoveAt(3);round.Windows[0].Opacity=float.NaN;rejects=false;try{DemoGame.ValidateLayoutJ(round);}catch(InvalidDataException){rejects=true;}Check(rejects,"malformed opacity rejected");Console.WriteLine(checks+" Stage J backend checks passed.");}
}
public sealed partial class DemoGame
{
 void RunUiChecksJ(int stage){if(captureScene!="stage-j-inventory")return;var windows=desktop.Where(w=>w.Kind==ViewMode.Inventory).OrderBy(w=>w.InventoryHangarJ).ToArray();if(windows.Length<2&&stage<10)throw new Exception("J UI fixture needs two inventories");void Click(string tip,DesktopWindow w){var h=ui.Hits.Last(h=>h.Owner==w.Owner&&h.Tip==tip);TestClick(h.Rect.Center.ToVector2());}switch(stage){case 1:UiCheck(windows[0].Owner!=windows[1].Owner,"independent inventories rendered");UiCheck(itemHits.Any(h=>h.Owner==windows[1].Owner&&h.Id=="ammo"),"hangar owned item hit");break;case 2:var source=itemHits.First(h=>h.Owner==windows[1].Owner&&h.Id=="ammo");var dest=dropHits.First(d=>d.Owner==windows[0].Owner&&!d.Hangar);float before=world.ItemCount("ammo",false);TestDrag(source.Rect.Center.ToVector2(),dest.Rect.Center.ToVector2());UiCheck(world.ItemCount("ammo",false)==before+12&&world.ItemCount("ammo",true)==0,"cross-instance drag transfers actual stack once");break;case 3:Click("Details",windows[0]);UiCheck(windows[0].InventoryViewJ==1&&windows[1].InventoryViewJ==0,"view modes remain independent");break;case 4:windows[0].Locked=true;var position=windows[0].Bounds;TestDrag(new(windows[0].X+220,windows[0].Y+12),new(windows[0].X+280,windows[0].Y+40));UiCheck(windows[0].Bounds==position,"locked header cannot move");windows[0].Locked=false;break;case 5:lastHeaderJ=null;TestDrag(new(windows[0].X+230,windows[0].Y+12),new(windows[0].X+250,windows[0].Y+25));UiCheck(windows[0].X==120&&windows[0].Y==123,"unlocked header moves and snaps to adjacent window");break;case 6:SaveDesktop();var saved=JsonSerializer.Deserialize<DesktopLayoutJ>(File.ReadAllText(LayoutPathJ))!;UiCheck(saved.Windows.Count(w=>w.Kind==ViewMode.Inventory&&w.OpenJ)==2,"two open instances saved");break;case 7:var item=itemHits.First(h=>h.Owner==windows[0].Owner);mouse=item.Rect.Center.ToVector2();ItemMenu(item);UiCheck(popupActions.Any(a=>a.Label=="Show info")&&popupActions.Any(a=>a.Label=="View market details"),"shared commands preserve item menu");context=false;break;case 8:float quantity=world.ItemCount("ammo",false);world.Undock();UiCheck(!ExecuteCommandJ(new("ammo",true),"transfer")&&world.ItemCount("ammo",false)==quantity,"disabled command does not mutate cargo");world.Screen=ViewMode.Station;world.Grid="station";break;case 9:StackJ(windows[0],windows[1]);UiCheck(windows[0].StackId==windows[1].StackId&&!StackVisibleJ(windows[1]),"stack has one active pane");break;case 10:var active=desktop.Last();UiCheck(ui.Hits.Any(h=>h.Tip.StartsWith("Activate window tab / ")),"stack tabs rendered");active.StackId="";foreach(var v in desktop)v.StackId="";break;case 11:EnsureWindow(ViewMode.DesktopSettingsJ);break;case 12:var settings=desktop.Last();Click("Search / Ctrl+A, Ctrl+C, Ctrl+V, Home, End",settings);JTextInput('m');JTextInput('a');UiCheck(settings.QueryJ=="ma","search field receives text");break;case 13:UiCheck(ui.Hits.Any(h=>h.Owner==desktop.Last().Owner&&h.Tip=="OPEN"),"filtered window table renders actions");editJ.Focus=false;textOwnerJ=null;break;case 14:SaveDesktop();var path=File.ReadAllText(LayoutPathJ);desktop.Clear();RestoreLayoutJ();UiCheck(desktop.Count>=3&&desktop.Count(w=>w.Kind==ViewMode.Inventory)==2,"layout reopen restores multiple inventories");Console.WriteLine("Stage J UI acceptance passed.");break;}oldMouse=Mouse.GetState();}
}
